import { fileURLToPath } from 'node:url';
import { stringify } from 'yaml';
import { buildOpenApiDocument } from '../src/openapi';

export const OPENAPI_PATH = fileURLToPath(new URL('../openapi.yaml', import.meta.url));

/** The exact text of openapi.yaml. A test compares it with the committed file. */
export function renderOpenApiYaml(): string {
  const header =
    '# Generated by `npm run openapi -w @deep-reef/contract` from packages/contract/src.\n' +
    '# Do not edit by hand: change the schemas and regenerate.\n';
  return header + stringify(buildOpenApiDocument(), { lineWidth: 0, aliasDuplicateObjects: false });
}
